#!/usr/bin/env bash
# Обновление сайта груминга: исправление ошибки «Application error» после отправки заявки.
# Запуск из папки проекта:  bash fix-zayavka.sh
set -euo pipefail
FILES="lib/db.ts lib/settings.ts lib/telegram.ts app/api/requests/route.ts app/api/admin/requests/route.ts app/r/[token]/page.tsx components/Booking.tsx components/admin/AdminApp.tsx db/schema.sql scripts/migrate.mjs"
PAYLOAD=''

say() { printf '\n\033[1;36m==> %s\033[0m\n' "$1"; }
die() { printf '\n\033[1;31mОШИБКА: %s\033[0m\n' "$1"; exit 1; }

cd "$(dirname "$0")"
[ -f package.json ] && grep -q '"grooming-salon"' package.json || die "Положите файл в папку проекта (там, где package.json) и запустите оттуда."

BACKUP="backup-$(date +%Y%m%d-%H%M%S)"
say "Сохраняю копию старых файлов в папку $BACKUP"
mkdir -p "$BACKUP"
for f in $FILES; do [ -f "$f" ] && { mkdir -p "$BACKUP/$(dirname "$f")"; cp "$f" "$BACKUP/$f"; }; done

say "Записываю исправленные файлы"
echo "$PAYLOAD" | base64 -d | tar xzf -

restore() {
  printf '\n\033[1;31mЧто-то пошло не так. Возвращаю старые файлы из %s\033[0m\n' "$BACKUP"
  cp -r "$BACKUP"/. ./
}

# --- Вариант 1: сайт работает в Docker (docker compose) ---
if command -v docker >/dev/null 2>&1 && [ -f docker-compose.yml ] && [ -n "$(docker compose ps -q app 2>/dev/null)" ]; then
  say "Сайт работает в Docker: пересобираю и перезапускаю (база исправится сама при старте)"
  docker compose up -d --build app || { restore; die "Сборка в Docker не удалась, старые файлы возвращены."; }
  sleep 5
  docker compose logs --tail=20 app
  say "Готово. Обновите страницу сайта (Ctrl+F5)."
  exit 0
fi

# --- Вариант 2: сайт запущен через Node.js напрямую (npm start / pm2) ---
command -v node >/dev/null 2>&1 || die "Не найден Node.js."
ENVF=""; [ -f .env ] && ENVF="--env-file=.env"

say "Исправляю уже сохранённые заявки и настройки в базе"
node $ENVF scripts/migrate.mjs || { restore; die "Не удалось подключиться к базе. Старые файлы возвращены. Проверьте DATABASE_URL в .env."; }

say "Собираю сайт (1–3 минуты)"
if ! npm run build; then restore; say "Пересобираю старую версию"; npm run build || true; die "Сборка не удалась, старые файлы возвращены. Пришлите вывод выше."; fi

say "Перезапускаю сайт"
RESTARTED=0
if command -v pm2 >/dev/null 2>&1; then
  IDS=$(pm2 jlist 2>/dev/null | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const cwd=process.argv[1];console.log(JSON.parse(s).filter(p=>p.pm2_env&&p.pm2_env.pm_cwd&&require("path").resolve(p.pm2_env.pm_cwd)===cwd).map(p=>p.pm_id).join(" "))}catch{}})' "$(pwd)")
  if [ -n "$IDS" ]; then pm2 restart $IDS && pm2 save >/dev/null 2>&1 || true; RESTARTED=1; fi
fi
if [ "$RESTARTED" = 0 ] && command -v systemctl >/dev/null 2>&1; then
  for u in $(systemctl list-units --type=service --state=running --no-legend 2>/dev/null | awk '{print $1}'); do
    if systemctl cat "$u" 2>/dev/null | grep -q "WorkingDirectory=$(pwd)\$"; then systemctl restart "$u" && RESTARTED=1 && echo "Перезапущен сервис $u"; fi
  done
fi
if [ "$RESTARTED" = 1 ]; then
  say "Готово. Обновите страницу сайта (Ctrl+F5)."
else
  printf '\n\033[1;33mФайлы обновлены и сайт собран, но не удалось найти, как он запущен.\nПерезапустите сайт так же, как запускали раньше (например: остановите npm start и запустите снова).\033[0m\n'
fi
